From f1b325a5d30ab5e00b8648694468bb903156e949 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 00:04:50 +0100
Subject: [PATCH] applets/kicker: keep the dashboard open when launching apps
 with Shift

Every launch from the Application Dashboard closed it, so opening many
apps meant reopening it each time. When Shift is held, the dashboard now
stays open and takes the focus back from the window of the launched app.

BUG: 451796
---
 applets/kicker/DashboardRepresentation.qml | 28 ++++++++++++++++++----
 1 file changed, 23 insertions(+), 5 deletions(-)

diff --git a/applets/kicker/DashboardRepresentation.qml b/applets/kicker/DashboardRepresentation.qml
index b0a6c9500c..9690b7a2c2 100644
--- a/applets/kicker/DashboardRepresentation.qml
+++ b/applets/kicker/DashboardRepresentation.qml
@@ -38,8 +38,19 @@ Kicker.DashboardWindow {
     readonly property int columns: Math.floor(((smallScreen ? 85 : 80)/100) * Math.ceil(width / cellSize))
     readonly property bool searching: searchField.text !== ""

+    // Windows of apps launched with Shift held, which must not close the dashboard
+    property int pendingKeptOpenLaunches: 0
+
     signal interactionConcluded()

+    function launchConcluded() : void {
+        if (keyboardModifiers() & Qt.ShiftModifier) {
+            pendingKeptOpenLaunches++;
+        } else {
+            interactionConcluded();
+        }
+    }
+
     keyEventProxy: searchField

     backgroundColor: "transparent"
@@ -54,12 +65,19 @@ Kicker.DashboardWindow {

     onActiveChanged: {
         if (!active && visible) {
-            root.interactionConcluded()
+            if (pendingKeptOpenLaunches > 0) {
+                pendingKeptOpenLaunches--;
+                raise();
+                requestActivate();
+            } else {
+                root.interactionConcluded()
+            }
         }
     }

     onVisibleChanged: {
         reset();
+        pendingKeptOpenLaunches = 0;

         if (visible) {
             preloadAllAppsTimer.restart();
@@ -475,7 +493,7 @@ Kicker.DashboardWindow {

                     Behavior on opacity { SmoothedAnimation { duration: Kirigami.Units.longDuration; velocity: 0.01 } }

-                    onInteractionConcluded: root.interactionConcluded()
+                    onInteractionConcluded: root.launchConcluded()
                     onCurrentIndexChanged: {
                         preloadAllAppsTimer.defer();
                     }
@@ -685,7 +703,7 @@ Kicker.DashboardWindow {

                         model: funnelModel

-                        onInteractionConcluded: root.interactionConcluded()
+                        onInteractionConcluded: root.launchConcluded()
                         onCurrentIndexChanged: {
                             preloadAllAppsTimer.defer();
                         }
@@ -732,7 +750,7 @@ Kicker.DashboardWindow {

                     opacity: filterList.allApps && !root.searching ? 1.0 : 0.0

-                    onInteractionConcluded: root.interactionConcluded()
+                    onInteractionConcluded: root.launchConcluded()
                     onOpacityChanged: {
                         if (opacity === 1.0) {
                             allAppsGrid.flickableItem.contentY = 0;
@@ -785,7 +803,7 @@ Kicker.DashboardWindow {

                     opacity: root.searching ? 1.0 : 0.0

-                    onInteractionConcluded: root.interactionConcluded()
+                    onInteractionConcluded: root.launchConcluded()
                     onOpacityChanged: {
                         if (opacity === 1.0) {
                             mainColumn.visibleGrid = runnerGrid;
-- 
2.53.0

From 2ab0176106c2c7b1ceaf9ac342636f5e4e96b4d6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 00:04:50 +0100
Subject: [PATCH] applets/kicker: let the dashboard read the keyboard modifiers

Clicks on the Application Dashboard's grid items don't carry keyboard
modifiers to QML, so it can't tell whether Shift was held when an app
was launched. Expose the current modifiers on DashboardWindow for that.

BUG: 451796
---
 applets/kicker/dashboardwindow.cpp | 6 ++++++
 applets/kicker/dashboardwindow.h   | 2 ++
 2 files changed, 8 insertions(+)

diff --git a/applets/kicker/dashboardwindow.cpp b/applets/kicker/dashboardwindow.cpp
index ee8fe9a171..4ceb81302c 100644
--- a/applets/kicker/dashboardwindow.cpp
+++ b/applets/kicker/dashboardwindow.cpp
@@ -7,6 +7,7 @@
 #include "dashboardwindow.h"

 #include <QCoreApplication>
+#include <QGuiApplication>
 #include <QIcon>
 #include <QScreen>

@@ -123,6 +124,11 @@ void DashboardWindow::toggle()
     }
 }

+Qt::KeyboardModifiers DashboardWindow::keyboardModifiers() const
+{
+    return QGuiApplication::queryKeyboardModifiers();
+}
+
 bool DashboardWindow::event(QEvent *event)
 {
     if (event->type() == QEvent::PlatformSurface) {
diff --git a/applets/kicker/dashboardwindow.h b/applets/kicker/dashboardwindow.h
index 5d6dbc1efe..862cfda3d6 100644
--- a/applets/kicker/dashboardwindow.h
+++ b/applets/kicker/dashboardwindow.h
@@ -41,6 +41,8 @@ public:

     Q_INVOKABLE void toggle();

+    Q_INVOKABLE Qt::KeyboardModifiers keyboardModifiers() const;
+
 Q_SIGNALS:
     void mainItemChanged() const;
     void visualParentChanged() const;
-- 
2.53.0
